from micrograd.engine import Value


def numeric_grad(f, x, h=1e-6):
    return (f(x + h) - f(x - h)) / (2 * h)


def check(build, x0):
    x = Value(x0)
    y = build(x)
    y.backward()
    expected = numeric_grad(lambda v: build(Value(v)).data, x0)
    assert abs(x.grad - expected) < 1e-4, (x.grad, expected)


def test_exp():
    check(lambda x: x.exp(), 0.7)


