import { STORAGE_KEY, loadTodos, saveTodos } from "../src/todo/storage.js";

function memoryStorage(initial = {}) {
    const data = new Map(Object.entries(initial));
    return {
        getItem: (key) => (data.has(key) ? data.get(key) : null),
        setItem: (key, value) => data.set(key, String(value)),
    };
}

test("uses the key todos-react", () => {
    assert.equal(STORAGE_KEY, "todos-react");
});

test("starts empty when nothing is saved", () => {
    assert.deepEqual(loadTodos(memoryStorage()), []);
});

test("loads what it saved", () => {
    const storage = memoryStorage();
    const todos = [{ id: "a", title: "Buy milk", completed: true }];
    saveTodos(storage, todos);
    assert.deepEqual(loadTodos(storage), todos);
});

import assert from "node:assert/strict";
import { test } from "node:test";

import * as A from "../src/todo/constants.js";
import { todoReducer } from "../src/todo/reducer.js";

const start = () =>
    Object.freeze([
        Object.freeze({ id: "a", title: "Buy milk", completed: false }),
        Object.freeze({ id: "b", title: "Walk dog", completed: true }),
    ]);

const actions = [
    { type: A.ADD_ITEM, payload: { title: "Read" } },
    { type: A.UPDATE_ITEM, payload: { id: "a", title: "Buy oat milk" } },
    { type: A.REMOVE_ITEM, payload: { id: "a" } },
    { type: A.TOGGLE_ITEM, payload: { id: "a" } },
    { type: A.REMOVE_ALL_ITEMS },
    { type: A.TOGGLE_ALL, payload: { completed: true } },
    { type: A.REMOVE_COMPLETED_ITEMS },
];

for (const action of actions) {
    test(`${action.type} returns a new array and keeps the old one`, () => {
        const state = start();
        const next = todoReducer(state, action);
        assert.notEqual(next, state);
        assert.deepEqual(state, start());
    });
}

test("ignores a value that is not JSON", () => {
    assert.deepEqual(loadTodos(memoryStorage({ [STORAGE_KEY]: "not json" })), []);
});

test("ignores saved JSON that is not a list", () => {
    assert.deepEqual(loadTodos(memoryStorage({ [STORAGE_KEY]: '{"title":"Buy milk"}' })), []);
});

test("migrates the old {text, done} shape", () => {
    const old = JSON.stringify([{ text: "Buy milk", done: true }]);
    const [todo] = loadTodos(memoryStorage({ [STORAGE_KEY]: old }));
    assert.deepEqual(Object.keys(todo).sort(), ["completed", "id", "title"]);
    assert.equal(todo.title, "Buy milk");
    assert.equal(todo.completed, true);
    assert.ok(todo.id.length > 0);
});

import assert from "node:assert/strict";
import { test } from "node:test";

import { TOGGLE_ITEM } from "../src/todo/constants.js";
import { filterTodos } from "../src/todo/filter.js";
import { todoReducer } from "../src/todo/reducer.js";

const todos = [
    { id: "a", title: "Buy milk", completed: false },
    { id: "b", title: "Walk dog", completed: true },
];
const ids = (list) => list.map((todo) => todo.id);

test("each route shows its todos", () => {
    assert.deepEqual(ids(filterTodos(todos, "/")), ["a", "b"]);
    assert.deepEqual(ids(filterTodos(todos, "/active")), ["a"]);
    assert.deepEqual(ids(filterTodos(todos, "/completed")), ["b"]);
});

test("a todo checked on /active leaves that view", () => {
    const next = todoReducer(todos, { type: TOGGLE_ITEM, payload: { id: "a" } });
    assert.deepEqual(filterTodos(next, "/active"), []);
});

test("an unknown route shows every todo", () => {
    assert.deepEqual(ids(filterTodos(todos, "/unknown")), ["a", "b"]);
});

test("LOAD_ITEMS replaces the list instead of adding to it", () => {
    const saved = [{ id: "a", title: "Buy milk", completed: false }];
    let state = todoReducer(start(), { type: A.LOAD_ITEMS, payload: { todos: saved } });
    state = todoReducer(state, { type: A.LOAD_ITEMS, payload: { todos: saved } });
    assert.deepEqual(state, saved);
});

from smolagents import ChatMessage, LogLevel, MessageRole, Model, ToolCallingAgent
from smolagents.memory import ActionStep
from smolagents.models import ChatMessageToolCall, ChatMessageToolCallFunction


class ScriptedModel(Model):
    """Plays back fixed tool calls, one per step, instead of asking an LLM."""

    def __init__(self, script):
        super().__init__(model_id="scripted")
        self.script = script  # list of (tool_name, arguments); the last one repeats
        self.calls = 0

    def generate(self, messages, stop_sequences=None, response_format=None, tools_to_call_from=None, **kwargs):
        self.calls += 1
        if tools_to_call_from is None:  # after max_steps the agent asks for a plain-text answer
            return ChatMessage(role=MessageRole.ASSISTANT, content="no answer")
        name, arguments = self.script[min(self.calls, len(self.script)) - 1]
        function = ChatMessageToolCallFunction(name=name, arguments=arguments)
        call = ChatMessageToolCall(id=f"call_{self.calls}", type="function", function=function)
        return ChatMessage(role=MessageRole.ASSISTANT, content="", tool_calls=[call])


if __name__ == "__main__":
    model = ScriptedModel([("search_web", {"query": "smolagents"})])
    agent = ToolCallingAgent(
        tools=[], model=model, max_steps=3, verbosity_level=LogLevel.OFF, return_full_result=True
    )
    result = agent.run("Find the smolagents docs.")
    for step in agent.memory.steps:
        if isinstance(step, ActionStep):
            outcome = type(step.error).__name__ if step.error else "ok"
            print("step", step.step_number, outcome, step.error or step.observations)
    print("state", result.state)
    print("model calls", model.calls)

from scripted import ScriptedModel
from smolagents import LogLevel, ToolCallingAgent


def score(steps):
    """Summarize a run from RunResult.steps, a list of plain dicts."""
    actions = [step for step in steps if "step_number" in step]
    # TODO: count the tool calls the model asked for (model_output_message), the tool calls
    # the agent recorded (tool_calls), the steps with an error, and read the final answer
    return {"steps": len(actions), "asked": 0, "recorded": 0, "errors": 0, "answer": None}


def test_score_from_trace():
    script = [
        ("search_web", {"query": "docs"}),
        ("search_web", {"query": "docs"}),
        ("final_answer", {"answer": "done"}),
    ]
    agent = ToolCallingAgent(
        tools=[], model=ScriptedModel(script), max_steps=5, verbosity_level=LogLevel.OFF, return_full_result=True
    )
    result = agent.run("Find the docs.")
    assert score(result.steps) == {"steps": 3, "asked": 3, "recorded": 1, "errors": 2, "answer": "done"}

def test_cursor_paging_survives_insert(client: TestClient, db: Session) -> None:
    owner, headers = make_owner(client, db)
    items = [add_item(db, owner, f"item {i}") for i in range(5)]
    expected = [str(item.id) for item in reversed(items)]
    seen: list[str] = []
    params: dict[str, str | int] = {"limit": 2}
    for page in range(10):
        body = client.get(URL, headers=headers, params=params).json()
        seen += [item["id"] for item in body["data"]]
        if page == 0:
            add_item(db, owner, "inserted between pages")
        if body["next_cursor"] is None:
            break
        params["after"] = body["next_cursor"]
    assert seen == expected
    assert page == 2  # three requests: 2 + 2 + 1 items

import numpy as np
import torch as th
from gymnasium import spaces
from stable_baselines3.common.buffers import RolloutBuffer


def discounted_returns(rewards, gamma):
    raise NotImplementedError  # TODO: G_t = r_t + gamma * G_(t+1), from the last step back


def fill(gae_lambda):
    buf = RolloutBuffer(3, spaces.Box(-1, 1, (1,)), spaces.Discrete(2),
                        device="cpu", gae_lambda=gae_lambda, gamma=0.9)
    for step in range(3):
        buf.add(np.zeros((1, 1)), np.zeros((1, 1)), np.array([1.0]),
                np.array([step == 0]), th.zeros(1), th.zeros(1))
    buf.compute_returns_and_advantage(last_values=th.zeros(1), dones=np.array([True]))
    return buf.returns.flatten().tolist()


def test_lambda_one_matches_discounted_returns():
    assert np.allclose(fill(1.0), discounted_returns([1, 1, 1], 0.9))


def test_lambda_zero_is_one_step_target():
    assert np.allclose(fill(0.0), [1.0, 1.0, 1.0])

describe('authority table', () => {
  // Every action kind once; santa.rule.set twice, because only 'allow' releases.
  const contain: Action[] = [
    { kind: 'process.suspend', pid: 7 },
    { kind: 'process.kill', pid: 7 },
    { kind: 'network.block', address: '203.0.113.9' },
    { kind: 'file.quarantine', path: '/tmp/x' },
    { kind: 'santa.rule.set', ruleType: 'teamid', identifier: 'X', policy: 'block' },
    { kind: 'persistence.disable', path: '/Library/LaunchAgents/x.plist' },
  ];
  const release: Action[] = [
    { kind: 'process.resume', pid: 7 },
    { kind: 'network.unblock', address: '203.0.113.9' },
    { kind: 'file.restore', quarantineId: 'q1' },
    { kind: 'santa.rule.set', ruleType: 'teamid', identifier: 'X', policy: 'allow' },
    { kind: 'santa.rule.remove', ruleType: 'teamid', identifier: 'X' },
    { kind: 'persistence.enable', path: '/Library/LaunchAgents/x.plist' },
  ];
  const rows = release.flatMap((action) => (['ai', 'rule'] as const).map((actor) => ({ actor, action })));

  it('lists every action kind', () => {
    expect(new Set([...contain, ...release].map((a) => a.kind))).toEqual(new Set(ActionKind.options));
  });

  it.each(rows)('$actor may not run or propose $action.kind', ({ actor, action }) => {
    expect(isRelease(action)).toBe(true);
    expect(authorizeAction(actor, action)).toEqual({ ok: false, reason: 'TODO' }); // TODO: per actor
    expect(canPropose(actor, action).ok).toBe(false);
  });

  it.each(contain)('a rule may run $kind; the AI may only propose it', (action) => {
    expect(authorizeAction('rule', action).ok).toBe(true);
    expect(authorizeAction('ai', action).ok).toBe(false);
    expect(canPropose('ai', action).ok).toBe(true);
  });
});

