import { DatabaseSync } from 'node:sqlite';
import { describe, expect, it } from 'vitest';
import { AlertService } from './alerts.js';
import { Store } from './db/store.js';
import { DryRunExecutor } from './executor.js';
import { makeExec, makeRule } from './testing.js';

const rule = makeRule({ mode: 'alert', severity: 'high', fidelity: 'high' });

/** One app run: a store on the database file and an alert service with a fixed clock. */
function open(file: string, now: number) {
  const store = new Store(new DatabaseSync(file));
  const executor = new DryRunExecutor();
  const svc = new AlertService(store, executor, () => now);
  const popups: string[] = [];
  svc.on('popup', (a) => popups.push(a.id));
  return { store, svc, popups, executor };
}

describe('restart', () => {
  it('folds a repeat into the stored alert after a restart', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'vigil-restart-'));
    const file = join(dir, 'vigil.sqlite3');
    try {
      const first = open(file, 1_000_000);
      const a = await first.svc.raise({ rule, events: [makeExec()], actions: [] });
      first.store.close(); // the app quits
      const second = open(file, 1_000_000 + 60_000); // started again a minute later
      const b = await second.svc.raise({ rule, events: [makeExec()], actions: [] });
      console.log(JSON.stringify({ same: b.id === a.id, count: b.repeats?.count,
        open: second.store.listAlerts({ status: 'open' }).length, popups: second.popups.length }));
      // TODO: expect() the values you printed
      second.store.close();
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

